"""Build portable, offline HTML viewers from measured MATLAB/Simulink results."""
from pathlib import Path
import csv, json, html
ROOT=Path(__file__).resolve().parents[1]
def rows(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
from presentation import page

s=ROOT; summary=json.loads((s/'results/summary.json').read_text()); reports=summary['results']; traces={}
for r in reports:
    raw=rows(s/'results'/f'{r["scenario"]}.csv');traces[r['scenario']]=[{k:float(v) for k,v in row.items()} for row in raw]
nom=next(r for r in reports if r['scenario']=='nominal');em=next(r for r in reports if r['scenario']=='emergency_stop')
content='''<header><div class="eyebrow">PROYECTO 02 / SIMULINK / LÍNEAS AUTOMATIZADAS</div><h1>Servo Transfer Cell</h1><p class="intro">Puesta en marcha virtual de una estación de transferencia. Reproduce el movimiento, la secuencia y los interbloqueos a partir de trazas del solver de Simulink.</p><span class="badge">Simulación real ejecutada · Modelo reconstruible desde código</span></header>
<section class="grid"><div class="card"><div class="muted">Escenarios aprobados</div><div class="metric">'''+str(len(reports))+''' / '''+str(len(reports))+'''</div><small>Operación, perturbaciones e inyección de fallos</small></div><div class="card"><div class="muted">Ciclo nominal medido</div><div class="metric">'''+f'{nom["cycleTime"]:.2f}'+''' s</div><small>Desde inicio hasta retorno completado</small></div><div class="card"><div class="muted">Distancia de parada simulada</div><div class="metric">'''+f'{em["stopDistance"]*1000:.1f}'+''' mm</div><small>Modelo de freno idealizado; no validación de seguridad</small></div></section>
<section class="card"><h2>Reproduce una prueba</h2><div class="controls"><label for="scenario">Escenario</label><select id="scenario">'''+''.join(f'<option value="{r["scenario"]}">{r["scenario"].replace("_"," ")}</option>' for r in reports)+'''</select><button id="play">Reproducir</button><label for="time">Tiempo</label><input id="time" type="range" min="0" max="1600" value="0" step="1"><output id="clock">0.00 s</output></div>
<svg viewBox="0 0 1000 235" role="img" aria-label="Posición del carro de transferencia"><rect x="75" y="125" width="850" height="20" rx="6" fill="#e3e8ee"/><line x1="100" y1="135" x2="880" y2="135" stroke="#61718a" stroke-width="3"/><rect x="719" y="30" width="140" height="65" rx="9" fill="#f6f9fc" stroke="#a8c3de"/><text x="789" y="65" text-anchor="middle" font-size="16" fill="#273951">Estación de trabajo</text><line x1="789" y1="100" x2="789" y2="160" stroke="#a8c3de" stroke-dasharray="5 5"/><text x="126" y="185" font-size="15" fill="#61718a">Origen · 0 m</text><text x="731" y="185" font-size="15" fill="#61718a">Objetivo · 0.65 m</text><g id="carriage"><rect x="-31" y="90" width="62" height="34" rx="7" fill="#665efd"/><rect x="-17" y="68" width="34" height="22" rx="3" fill="#f5e9d4"/><circle cx="-19" cy="126" r="7" fill="#0d253d"/><circle cx="19" cy="126" r="7" fill="#0d253d"/></g></svg>
<div class="grid"><div><small>Estado</small><div id="state" class="metric"></div></div><div><small>Velocidad / fuerza</small><div id="motion"></div></div><div><small>Alarma / ciclos</small><div id="alarm"></div></div></div><svg id="trace" viewBox="0 0 1000 240" role="img" aria-label="Traza de posición y cursor de tiempo"></svg></section>
<section class="card"><h2>Evidencia de aceptación</h2><div class="scroll"><table><thead><tr><th>Escenario</th><th>Resultado</th><th>Ciclos</th><th>Alarma final</th></tr></thead><tbody>'''+''.join(f'<tr><td>{r["scenario"].replace("_"," ")}</td><td>PASS</td><td>{r["cycles"]}</td><td>{r["finalAlarm"]}</td></tr>' for r in reports)+'''</tbody></table></div><p><a href="../README.md">README</a> · <a href="../results/acceptance.csv">Resultados CSV</a> · <a href="requirements.md">Requisitos</a> · <a href="defensa-es.md">Guía de entrevista</a></p></section><p class="note">Esta animación reproduce datos ya simulados; no controla hardware. No existe conexión a PLC ni robot y la parada de emergencia representada no es una función de seguridad certificada.</p>'''
script='const traces='+json.dumps(traces,separators=(',',':'))+''';const names=['IDLE','INDEX','PROCESS','RETURN','COMPLETE','FAULT','MANUAL'];const choice=document.getElementById('scenario'),slider=document.getElementById('time'),play=document.getElementById('play');let running=false,previous=null,fractional=0;function update(){const d=traces[choice.value];slider.max=d.length-1;const i=Math.min(+slider.value,d.length-1),r=d[i];document.getElementById('clock').textContent=r.time.toFixed(2)+' s';document.getElementById('state').textContent=names[Math.round(r.state)];document.getElementById('state').style.color=r.state===5?'#ea2261':'#665efd';document.getElementById('motion').textContent=r.velocity.toFixed(3)+' m/s · '+r.force.toFixed(1)+' N';document.getElementById('alarm').textContent='Código '+r.alarm+' · '+r.cycles+' ciclo(s)';document.getElementById('carriage').setAttribute('transform','translate('+(160+r.position*968)+',0)');let pts=d.filter((_,k)=>k%4===0).map(a=>(55+a.time*56.5)+','+(185-a.position*200)).join(' ');let cursor=55+r.time*56.5;document.getElementById('trace').innerHTML='<line x1="55" y1="185" x2="960" y2="185" stroke="#e3e8ee"/><line x1="55" y1="55" x2="960" y2="55" stroke="#e3e8ee" stroke-dasharray="5 5"/><text x="5" y="60" font-size="13" fill="#61718a">0.65 m</text><text x="20" y="190" font-size="13" fill="#61718a">0</text><polyline points="'+pts+'" fill="none" stroke="#665efd" stroke-width="2.5"/><line x1="'+cursor+'" y1="25" x2="'+cursor+'" y2="200" stroke="#9b6829" stroke-width="2"/><text x="55" y="228" font-size="13" fill="#61718a">Posición medida · 0–16 segundos</text>'}function tick(now){if(running){if(previous!==null){const next=+slider.value+fractional+(now-previous)/10;fractional=next-Math.floor(next);slider.value=Math.min(+slider.max,Math.floor(next));update();if(+slider.value>=+slider.max){running=false;play.textContent='Reproducir'}}previous=now}else previous=null;requestAnimationFrame(tick)}play.onclick=()=>{if(+slider.value>=+slider.max)slider.value=0;running=!running;play.textContent=running?'Pausar':'Reproducir'};choice.onchange=()=>{slider.value=0;running=false;play.textContent='Reproducir';update()};slider.oninput=update;update();requestAnimationFrame(tick);'''
(s/'docs/demo.html').write_text(page('Servo Transfer Cell — demo',content,script),encoding='utf-8')

print("Offline viewer generated from results.")

(ROOT/"docs/index.html").write_text((ROOT/"docs/demo.html").read_text(encoding="utf-8"),encoding="utf-8")
